// Extract weather data and prepare for simulation
const weatherData = $input.first().json;
const location = weatherData.location || 'default';
const climateZone = weatherData.climate_zone || 'temperate';
const altitude = weatherData.altitude || 0;
const season = weatherData.season || 'summer';
const currentTime = weatherData.timestamp || new Date().toISOString();

// Calculate environmental factors
const temperature = weatherData.temperature || 20;
const humidity = weatherData.humidity || 0.5;
const pressure = weatherData.pressure || 1013.25;
const windSpeed = weatherData.wind_speed || 5;
const visibility = weatherData.visibility || 10;

// Determine weather severity
let severity = 'mild';
const weatherScore = Math.abs(temperature - 20) * 0.1 + windSpeed * 0.05 + (1 - visibility / 10) * 0.3;
if (weatherScore > 0.8) severity = 'extreme';
else if (weatherScore > 0.6) severity = 'severe';
else if (weatherScore > 0.4) severity = 'moderate';
else if (weatherScore > 0.2) severity = 'mild';
else severity = 'calm';

// Select weather type based on conditions
let weatherType = 'clear';
if (humidity > 0.8 && temperature < 0) weatherType = 'snow';
else if (humidity > 0.7 && pressure < 1010) weatherType = 'rain';
else if (humidity > 0.6 && pressure < 1005) weatherType = 'thunderstorm';
else if (humidity > 0.9) weatherType = 'fog';
else if (windSpeed > 30) weatherType = 'strong_wind';
else if (temperature > 35) weatherType = 'heat_wave';
else if (temperature < -15) weatherType = 'blizzard';

return [{
  json: {
    location,
    climate_zone: climateZone,
    altitude,
    season,
    timestamp: currentTime,
    weather_type: weatherType,
    severity,
    temperature,
    humidity,
    pressure,
    wind_speed: windSpeed,
    visibility,
    magical_intensity: weatherData.magical_intensity || 0,
    magical_source: weatherData.magical_source || null
  }
}];

// Analyze simulation results and determine impacts
const simulationResult = $input.first().json;
const newWeatherState = simulationResult.new_state;
const transitionData = simulationResult.transition_data;

// Calculate environmental impacts
const impacts = {
  movement: {
    speed_modifier: newWeatherState.weather_type.includes('rain') ? 0.7 : 
                  newWeatherState.weather_type.includes('snow') ? 0.5 :
                  newWeatherState.weather_type.includes('storm') ? 0.3 : 1.0,
    endurance_cost: newWeatherState.wind_speed > 30 ? 1.5 : 1.0,
    navigation_difficulty: newWeatherState.visibility < 5 ? 2.0 : 1.0
  },
  combat: {
    ranged_attack_penalty: newWeatherState.wind_speed > 25 ? -3 : 
                         newWeatherState.visibility < 8 ? -2 : 0,
    concentration_dc: newWeatherState.weather_type.includes('storm') ? 15 : 10,
    spell_effectiveness: newWeatherState.magical_intensity > 0.5 ? 1.3 : 1.0
  },
  sensory: {
    visibility_range: newWeatherState.visibility,
    perception_modifier: newWeatherState.visibility < 5 ? -3 : 
                       newWeatherState.weather_type.includes('fog') ? -4 : 0,
    stealth_bonus: newWeatherState.visibility < 8 ? 2 : 0
  },
  hazards: [],
  special_conditions: []
};

// Identify hazards
if (newWeatherState.temperature < -20) impacts.hazards.push('extreme_cold');
if (newWeatherState.temperature > 40) impacts.hazards.push('extreme_heat');
if (newWeatherState.wind_speed > 60) impacts.hazards.push('dangerous_winds');
if (newWeatherState.weather_type === 'blizzard') impacts.hazards.push('whiteout_conditions');
if (newWeatherState.weather_type === 'thunderstorm') impacts.hazards.push('lightning_strike_risk');

// Identify special conditions
if (newWeatherState.magical_intensity > 0.5) {
  impacts.special_conditions.push(`magical_weather_${newWeatherState.magical_source}`);
}
if (newWeatherState.pressure < 990) impacts.special_conditions.push('approaching_storm');
if (newWeatherState.pressure > 1030) impacts.special_conditions.push('high_pressure_system');

// Generate weather event if significant change
const weatherEvent = transitionData.significant_change ? {
  event_type: transitionData.change_type,
  description: transitionData.description,
  impact_level: newWeatherState.severity,
  affected_systems: ['movement', 'combat', 'sensory'],
  duration_minutes: 60 * (newWeatherState.severity === 'extreme' ? 6 : 3)
} : null;

return [{
  json: {
    weather_state: newWeatherState,
    environmental_impacts: impacts,
    weather_event: weatherEvent,
    simulation_metadata: {
      timestamp: new Date().toISOString(),
      confidence: simulationResult.confidence || 0.85,
      next_update: new Date(Date.now() + 15 * 60 * 1000).toISOString()
    }
  }
}];

